Ts = 0.05;
N = 2000;
u = idinput(N, 'prbs', [0 0.3], [-1 1]);
sysTrue = c2d(tf(2, [1 1.2 4]), Ts);
y = lsim(sysTrue, u) + 0.02*randn(N, 1);
data = iddata(y, u, Ts, 'InputName', 'force', 'OutputName', 'displacement');
data = detrend(data);
dataTrain = data(1:1400);
dataVal = data(1401:end);
plot(dataTrain)

opt = tfestOptions('InitMethod', 'iv', 'EnforceStability', true, 'Display', 'on');
sys = tfest(dataTrain, 2, 0, NaN, opt);
disp(sys)
fprintf('Fit on validation data: ');
compare(dataVal, sys);
fprintf('%.1f%%\n', sys.Report.Fit.FitPercent);

sys = ssest(dataTrain, 1:8);        % choose the order interactively
sys4 = ssest(dataTrain, 4, 'Ts', 0, 'DisturbanceModel', 'estimate');
compare(dataVal, sys4);
figure, resid(dataVal, sys4);
fprintf('Order %d, fit %.1f%%\n', order(sys4), sys4.Report.Fit.FitPercent);

NN = struc(1:6, 1:6, 1:3);
V = arxstruc(dataTrain, dataVal, NN);
orders = selstruc(V, 'aic');
fprintf('Selected [na nb nk] = %s\n', mat2str(orders));
sys = arx(dataTrain, orders);
compare(dataVal, sys);

sysArx = arx(dataTrain, [2 2 1]);
sysArmax = armax(dataTrain, [2 2 2 1]);
compare(dataVal, sysArx, sysArmax);
legend show
figure, resid(dataVal, sysArmax);
fprintf('ARX %.1f%%, ARMAX %.1f%%\n', ...
    sysArx.Report.Fit.FitPercent, sysArmax.Report.Fit.FitPercent);

sys = n4sid(dataTrain, 1:10);     % shows the singular value plot
sysInit = n4sid(dataTrain, 4);
opt = ssestOptions('SearchMethod', 'lm');
sysRefined = ssest(dataTrain, sysInit, opt);
compare(dataVal, sysInit, sysRefined);

sys = procest(dataTrain, 'P2DZ');
disp(sys)
fprintf('Kp = %.3f, Tp1 = %.3f s, Td = %.3f s\n', sys.Kp, sys.Tp1, sys.Td);
compare(dataVal, sys);
C = pidtune(tf(sys), 'PID');

sysLin = arx(dataTrain, [2 2 1]);
sysNL = nlarx(dataTrain, [2 2 1], idWaveletNetwork(8));
sysCustom = nlarx(dataTrain, [2 2 1], idLinear, ...
    'CustomRegressors', {'u1(t-1)^2', 'y1(t-1)*u1(t-1)'});
compare(dataVal, sysLin, sysNL, sysCustom);
legend show

[yh, fit, x0] = compare(dataVal, sysArmax, Inf);
fprintf('Simulation fit: %.2f%%\n', fit);
compare(dataVal, sysArx, sysArmax, sysNL);
legend show
compare(dataVal, sysArmax, 1);   % one-step-ahead prediction

resid(dataVal, sysArmax, 'corr');
res = resid(dataVal, sysArmax);
fprintf('Residual std: %.4f\n', std(res.OutputData));
figure, resid(dataVal, sysArx);    % ARX residuals will look worse

orders = 1:8;
fits = zeros(size(orders));
for k = orders
    m = ssest(dataTrain, k);
    ysim = sim(m, dataVal);
    fits(k) = goodnessOfFit(ysim.OutputData, dataVal.OutputData, 'NRMSE');
end
plot(orders, fits, 'o-'); xlabel('Model order'); ylabel('NRMSE fit')
[~, best] = max(fits);
fprintf('Best order: %d\n', orders(best));

