load noisdopp
[cA, cD] = dwt(noisdopp, 'db4');
fprintf('%d samples -> %d approx + %d detail\n', ...
    numel(noisdopp), numel(cA), numel(cD));
xr = idwt(cA, cD, 'db4');
fprintf('Reconstruction error: %.2e\n', max(abs(noisdopp(:) - xr(1:numel(noisdopp))')));

load noisdopp
[cA, cD] = dwt(noisdopp, 'sym4');
approxOnly = idwt(cA, [], 'sym4');
detailOnly = idwt([], cD, 'sym4');
plot(1:numel(noisdopp), noisdopp, 1:numel(approxOnly), approxOnly)
legend('original','lowpass part')

load noisdopp
[c, l] = wavedec(noisdopp, 5, 'sym6');
cA5 = appcoef(c, l, 'sym6', 5);
[cD1, cD2, cD3] = detcoef(c, l, [1 2 3]);
fprintf('Level-5 approximation has %d coefficients\n', numel(cA5));
xrec = waverec(c, l, 'sym6');

load noisdopp
[c, l] = wavedec(noisdopp, 5, 'db6');
thr = 2.5 * median(abs(c(l(1)+1:end))) / 0.6745;
cThresh = wthresh(c, 's', thr);
cThresh(1:l(1)) = c(1:l(1));     % keep the approximation untouched
clean = waverec(cThresh, l, 'db6');
plot(1:numel(noisdopp), noisdopp, 1:numel(clean), clean, 'LineWidth', 1.2)

load wecg
fs = 180;
w = modwt(wecg, 'sym4', 5);
mra = modwtmra(w, 'sym4');
t = (0:numel(wecg)-1)/fs;
for k = 1:6
    subplot(6,1,k), plot(t, mra(k,:)), ylabel(sprintf('L%d', k))
end
var_by_level = modwtvar(w, 'sym4');

load wecg
w = modwt(wecg, 'sym4', 6);
wBand = zeros(size(w));
wBand(3:5, :) = w(3:5, :);      % keep only levels 3 to 5
qrs = imodwt(wBand, 'sym4');
plot(1:numel(wecg), wecg, 1:numel(qrs), qrs + 2)
legend('ECG','levels 3-5')

X = im2double(imread('cameraman.tif'));
[c, s] = wavedec2(X, 3, 'bior3.7');
cA3 = appcoef2(c, s, 'bior3.7', 3);
[cH1, cV1, cD1] = detcoef2('all', c, s, 1);
thr = 0.05;
cComp = c .* (abs(c) > thr);
Xrec = waverec2(cComp, s, 'bior3.7');
fprintf('Kept %.1f%% of coefficients, PSNR %.1f dB\n', ...
    100*nnz(cComp)/numel(c), psnr(Xrec, X));

load noisdopp
[c, l] = wavedec(noisdopp, 5, 'sym6');
sigma = median(abs(c(end-l(end)+1:end))) / 0.6745;
T = sigma * sqrt(2*log(numel(noisdopp)));
cSoft = wthresh(c, 's', T);
cHard = wthresh(c, 'h', T);
plot(1:1024, waverec(cSoft, l, 'sym6'), 1:1024, waverec(cHard, l, 'sym6'))
legend('soft','hard')

